      ctx.dbox(cx, capY + 0.10, cz, R * 2.4, 0.20, R * 2.4, CAP);
      ctx.dbox(cx, capY + 0.26, cz, R * 2.9, 0.16, R * 2.9, shade(CAP, 1.04));
