    sx.strokeStyle = css(0x4a4e53); sx.lineWidth = 9;
    pathU(-58); sx.stroke();
    sx.strokeStyle = "rgba(238,242,246,.45)"; sx.lineWidth = 1.5;
    pathU(-58); sx.stroke();
