    J.shade();
    A.fill(hx(uni));
    A.rect("front", 0.15, 0.04, 0.70, 0.23, tone(uni, -0.28));
    A.rect("front", 0.15, 0.04, 0.70, 0.04, "#d9b94b");
    A.rect("side", 0.15, 0.04, 0.70, 0.23, tone(uni, -0.28));
    A.rect("front", 0, 0.88, 1, 0.12, tone(uni, -0.28));
