    const key = dims[0].toFixed(3) + "," + dims[1].toFixed(3) + "," + dims[2].toFixed(3);
    let g = yokeGeoms[key];
    if (g) return g;
    g = new THREE.BoxGeometry(dims[0], dims[1], dims[2]);
