  const PONTOON_FB = 0.42;                 // floating pontoon freeboard (0.3-0.5m, §G)
  const PONTOON_TOP = SEA_Y + PONTOON_FB;  // mean deck height of every pontoon
  const QUAY_TOP = 0.40;                   // fixed quay — a step-up (physics STEP_UP 0.45)

