    _fallbackDone = true;
    if (berths.length) return;
    const A = (CBZ.city && CBZ.city.arena) || CBZ._settlementArena || null;
    if (!A) return;
    const cz = A.center ? A.center.z : 0;
    const EEx = A.maxX + 26;                          // the east seawall line (world.js:1010)
